          },
          "Address2": {
            "type": "string",
            "description": "Second line of company address"
          },
          "Address3": {
            "type": "string",
            "description": "Third line of company address"
          },
          "BenifitConsiderFlg": {
            "type": "boolean",
            "description": "Flag to indicate if benefits were considered"
          },
          "Category": {
            "type": "string",
