            "description": "Department or division worked in"
          },
          "DesignationOnLeave": {
            "type": "string",
            "description": "Designation held when leaving the company"
          },
          "ExpEmail": {
            "type": "string",
            "description": "Email address associated with this work experience"
          },
          "ExpFromDate": {
            "type": "string",
            "format": "date-time",
            "description": "Start date of employment in ISO format"
          },
          "ExpFromDateStr": {
            "type": "string",
            "description": "Formatted start date of employment (DD/MM/YYYY)"
          },
          "ExpMonths": {
            "type": "integer",
            "description": "Number of months of experience in this role"
          },
          "ExpTelNo": {
            "type": "string",
            "description": "Contact telephone number during employment"
          },
          "ExpToDate": {
            "type": "string",
            "format": "date-time",
            "description": "End date of employment in ISO format"
          },
          "ExpToDateStr": {
            "type": "string",
            "description": "Formatted end date of employment (DD/MM/YYYY)"
          },
          "ExpYears": {
            "type": "integer",
            "description": "Number of years of experience in this role"
          },
          "IndustryTypeName": {
            "type": "string",
            "description": "Name of the industry type"
          },
          "IsInternalFlg": {
            "type": "integer",
            "description": "Flag indicating if the role was internal (1 = Yes, 0 = No)"
          },
          "ReasonForLeave": {
            "type": "string",
            "description": "Reason for leaving the company"
          },
          "Sequence": {
            "type": "integer",
            "description": "Sequence/order number of the work experience entry"
          },
          "UpdateInsert": {
            "type": "integer",
            "description": "Indicates update/insert action flag (system field)"
          },
          "WorkRelatedFlg": {
            "type": "boolean",
            "description": "Indicates if the work experience is work-related"
          }
        },
        "required": [
          "Accountabilities",
          "Achievments",
          "ActionType",
          "Address1",
          "Address2",
          "Address3",
          "BenifitConsiderFlg",
          "Category",
          "Company",
          "ContactPerson",
          "Department",
          "DesignationOnLeave",
          "ExpEmail",
          "ExpFromDate",
          "ExpFromDateStr",
          "ExpMonths",
          "ExpTelNo",
          "ExpToDate",
          "ExpToDateStr",
          "ExpYears",
          "IndustryTypeName",
          "IsInternalFlg",
          "ReasonForLeave",
          "Sequence",
          "UpdateInsert",
          "WorkRelatedFlg"
        ]
      },
      "minItems": 1,
      "uniqueItems": true
    }
  },
  "required": ["WorkExperienceRecords"]
}

basic.transformer:
(async function (data, args, reqOptions) {
  let finalData = args.WorkExperienceRecords.map(x => ({
    ...x,
    EmpNumber: window.empNumber1
  }));
  const myHeaders = new Headers();
  myHeaders.append("accept", "*/*");
  myHeaders.append("accept-language", "en-GB,en-US;q=0.9,en;q=0.8");
  myHeaders.append("content-type", "application/json");
  myHeaders.append("x-requested-with", "XMLHttpRequest");



  const raw = JSON.stringify(finalData);

  const requestOptions = {
    method: "POST",
    headers: myHeaders,
    body: raw,
    redirect: "follow"
  };

  const response = await fetch(`${window.origin}/hr/EIMV9/api/WorkExperienceAPI/SaveWorkExperience/`, requestOptions);
  return await response.json();
})

